package dev.bws.announcer.core

import dev.bws.announcer.R

/** Attention tones live in res/raw (generated by tools/make_chimes.py). */
object Chimes {
    fun resource(c: Chime): Int? = when (c) {
        Chime.OFF -> null
        Chime.SOFT_BELL -> R.raw.chime_soft_bell
        Chime.TWO_TONE -> R.raw.chime_two_tone
        Chime.RISING -> R.raw.chime_rising
        Chime.DROPLET -> R.raw.chime_droplet
        Chime.MARIMBA -> R.raw.chime_marimba
        Chime.GLASS -> R.raw.chime_glass
    }
}
